package io.knowledgebrain.space;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class GroupMembershipApiTest {
 GroupMembershipStore store;IdentityPrincipalClient identity;GroupMembershipController api;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID actor=ids.next(),group=ids.next();String parent="00-"+"a".repeat(32)+"-"+"b".repeat(16)+"-01";
 @BeforeEach void setup(){store=mock(GroupMembershipStore.class);identity=mock(IdentityPrincipalClient.class);api=new GroupMembershipController(store,identity,"https://localhost:8443");when(identity.resolve("c".repeat(43),parent)).thenReturn(new IdentityPrincipalClient.Principal(actor,"REGISTERED",Instant.now().plusSeconds(60)));}
 MockHttpServletRequest req(String method,String body){var r=new MockHttpServletRequest(method,"/api/groups/"+group+"/invitations");r.setSecure(true);r.addHeader("Cookie","__Host-brain_guest="+"c".repeat(43));r.addHeader("Origin","https://localhost:8443");r.addHeader("traceparent",parent);r.setContentType("application/json");r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void guestsAndDuplicateCredentialsNeverReachMembershipStore(){when(identity.resolve(anyString(),anyString())).thenReturn(new IdentityPrincipalClient.Principal(actor,"GUEST",Instant.now().plusSeconds(60)));assertThrows(ResponseStatusException.class,()->api.issue(group.toString(),req("POST","{\"role\":\"MEMBER\"}")));var duplicate=req("GET","");duplicate.addHeader("Cookie","__Host-brain_guest="+"c".repeat(43));assertThrows(ResponseStatusException.class,()->api.self(group.toString(),duplicate));verifyNoInteractions(store);}
 @Test void strictJsonOriginBodyAndCreationKeyAreRequired(){for(String body:List.of("{\"role\":\"MEMBER\",\"actorId\":\"forged\"}","{\"role\":\"MEMBER\",\"role\":\"VIEWER\"}","{\"role\":\"MEMBER\"} {}")){var r=req("POST",body);r.addHeader("Idempotency-Key","d".repeat(32));assertThrows(ResponseStatusException.class,()->api.issue(group.toString(),r));}assertThrows(ResponseStatusException.class,()->api.issue(group.toString(),req("POST","{\"role\":\"MEMBER\"}")));var foreign=req("POST","{}");foreign.addHeader("Origin","https://evil.example");assertThrows(ResponseStatusException.class,()->api.accept(foreign));var get=req("GET","{}");assertThrows(ResponseStatusException.class,()->api.members(group.toString(),get));verifyNoInteractions(store);}
 @Test void singletonCurrentMembershipVersionRequired(){var id=ids.next().toString();assertEquals(428,assertThrows(ResponseStatusException.class,()->api.change(group.toString(),id,req("PUT","{\"role\":\"VIEWER\"}"))).getStatusCode().value());var duplicate=req("DELETE","");duplicate.addHeader("If-Match","\"gm1\"");duplicate.addHeader("If-Match","\"gm1\"");assertThrows(ResponseStatusException.class,()->api.remove(group.toString(),id,duplicate));verifyNoInteractions(store);}
 @Test void credentialClassesNeverExposeSecrets(){assertFalse(new GroupMembershipStore.Issued(null,"sensitive").toString().contains("sensitive"));var codes=new GroupInvitationCodes(Base64.getUrlEncoder().withoutPadding().encodeToString(new byte[32]));var code=codes.generate(ids.next());assertTrue(GroupInvitationCodes.valid(code));assertEquals(32,GroupInvitationCodes.hash(code).length);assertFalse(GroupInvitationCodes.valid("a".repeat(43)));}
 @Test void generatedTraceCorrelatesIdentityAndOutboxWhenCallerOmitsParent()throws Exception{var r=req("POST","{\"role\":\"MEMBER\"}");r.removeHeader("traceparent");r.addHeader("Idempotency-Key","d".repeat(32));when(identity.resolve(anyString(),anyString())).thenReturn(new IdentityPrincipalClient.Principal(actor,"REGISTERED",Instant.now().plusSeconds(60)));api.issue(group.toString(),r);var identityTrace=org.mockito.ArgumentCaptor.forClass(String.class);var eventTrace=org.mockito.ArgumentCaptor.forClass(String.class);verify(identity).resolve(eq("c".repeat(43)),identityTrace.capture());verify(store).issue(eq(group),eq(actor),eq("d".repeat(32)),eq("MEMBER"),eventTrace.capture());assertEquals(identityTrace.getValue().substring(3,35),eventTrace.getValue());}

}
